import React from 'react';
import './Stats.css';

const STATS = [
  { value: '230+', label: 'Successful Projects' },
  { value: '1000+', label: 'Happy Clients' },
  { value: '02+', label: 'Global Locations' },
  { value: '95%', label: 'Client Retention' },
];

export default function Stats() {
  return (
    <section className="stats-section bg-black text-white border-y border-black">
      <div className="container py-12 lg:py-16">
        <div className="stats__grid grid grid-cols-2 lg:grid-cols-4 gap-8 lg:gap-12">
          {STATS.map((stat, index) => (
            <div key={index} className="stats__item flex flex-col gap-2">
              <div className="stats__line w-8 h-1 bg-blue-600 mb-2" />
              <span className="stats__value font-display text-4xl lg:text-5xl font-bold">
                {stat.value}
              </span>
              <span className="stats__label font-mono text-[10px] uppercase tracking-widest text-gray-400">
                {stat.label}
              </span>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
